'use client';

import { ProfileHeader } from './profile-header';
import { ProfileSidebar } from './profile-sidebar';
import { useHeaderScrollProgress } from '@/hooks';

interface ProfileLayoutClientProps {
  slug: string;
  children: React.ReactNode;
}

export function ProfileLayoutClient({
  slug,
  children,
}: ProfileLayoutClientProps) {
  // Scroll progress (0-1) for header collapse and background animation
  const { progress } = useHeaderScrollProgress({ threshold: 150 });

  return (
    <div
      className="min-h-screen"
      style={{
        backgroundImage: `url(/main_background_light.png)`,
        backgroundRepeat: 'no-repeat',
        backgroundSize: '100% auto',
        backgroundPosition: `center ${-progress * 16}%`,
        transition: 'background-position 0.1s ease-out',
      }}
    >
      {/* Morphing Header - transforms from expanded to collapsed based on scroll progress */}
      <ProfileHeader slug={slug} progress={progress} />

      {/* Main Content Area */}
      <main className="max-w-6xl mx-auto pb-8">
        <div className="flex flex-col lg:flex-row gap-6">
          {/* Content Area */}
          <div className="flex-1 min-w-0">{children}</div>

          {/* Desktop Sidebar */}
          <aside className="hidden lg:block w-80 shrink-0">
            <div className="sticky top-20">
              <ProfileSidebar slug={slug} />
            </div>
          </aside>
        </div>
      </main>
    </div>
  );
}
