'use client';

import { useCallback } from 'react';
import { useModalContext } from '@/lib/modal-context';
import type { UseModalReturn, ModalConfig, BaseModalProps } from '@/types/modal';

/**
 * Hook for managing modals.
 *
 * @example
 * ```tsx
 * const { openModal, closeModal } = useModal();
 *
 * const handleClick = () => {
 *   openModal({
 *     component: MyModal,
 *     props: { title: 'Hello' },
 *     callbacks: {
 *       onClose: (result) => console.log('Closed with:', result),
 *     },
 *   });
 * };
 * ```
 */
export function useModal(): UseModalReturn {
  const { modals, openModal: contextOpenModal, closeModal: contextCloseModal, closeAllModals } =
    useModalContext();

  const openModal = useCallback(
    <TProps extends BaseModalProps, TResult = void>(
      config: ModalConfig<TProps, TResult>
    ): string => {
      return contextOpenModal(config);
    },
    [contextOpenModal]
  );

  const closeModal = useCallback(
    (id?: string, result?: unknown) => {
      if (id) {
        contextCloseModal(id, result);
      } else if (modals.length > 0) {
        // Close the topmost modal
        const topModal = modals[modals.length - 1];
        contextCloseModal(topModal.id, result);
      }
    },
    [contextCloseModal, modals]
  );

  return {
    openModal,
    closeModal,
    closeAllModals,
    isAnyModalOpen: modals.length > 0,
    modalCount: modals.length,
  };
}
