'use client';

import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/lib/utils';
import { useSkeletonLoading } from '@/lib/skeleton-context';
import { Skeleton } from './skeleton';

const textVariants = cva('', {
  variants: {
    variant: {
      body: 'text-base',
      heading: 'text-xl font-semibold',
      muted: 'text-sm text-muted-foreground',
    },
  },
  defaultVariants: {
    variant: 'body',
  },
});

// Map text sizes to skeleton heights (roughly matching line-height)
const textSizeToSkeletonHeight: Record<string, string> = {
  'text-xs': 'h-3',
  'text-sm': 'h-3.5',
  'text-base': 'h-4',
  'text-lg': 'h-5',
  'text-xl': 'h-5',
  'text-2xl': 'h-6',
  'text-3xl': 'h-7',
  'text-4xl': 'h-9',
  'text-5xl': 'h-12',
};

// Map variant to its base text size
const variantToTextSize: Record<string, string> = {
  body: 'text-base',
  heading: 'text-xl',
  muted: 'text-sm',
};

function getSkeletonHeight(variant: string | null | undefined, className?: string): string {
  // First, check if className contains a text size override
  if (className) {
    for (const [textClass, heightClass] of Object.entries(textSizeToSkeletonHeight)) {
      if (className.includes(textClass)) {
        return heightClass;
      }
    }
  }

  // Fall back to variant's default text size
  const variantTextSize = variantToTextSize[variant || 'body'];
  return textSizeToSkeletonHeight[variantTextSize] || 'h-4';
}

// const variantToSkeletonVariant = {
//   body: 'text',
//   heading: 'heading',
//   muted: 'text',
// } as const;

type TextElement = 'span' | 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6' | 'div';

export interface TextProps
  extends React.HTMLAttributes<HTMLElement>,
  VariantProps<typeof textVariants> {
  as?: TextElement;
  loading?: boolean;
}

function Text({
  className,
  variant,
  as: Component = 'span',
  loading,
  children,
  ...props
}: TextProps) {
  const isLoading = useSkeletonLoading(loading);

  if (isLoading) {
    const skeletonHeight = getSkeletonHeight(variant, className);
    // const skeletonVariant = variantToSkeletonVariant[variant || 'body'];
    return <Skeleton className={cn(skeletonHeight, className)} />;
  }

  return (
    <Component
      data-slot="text"
      className={cn(textVariants({ variant }), className)}
      {...props}
    >
      {children}
    </Component>
  );
}

export { Text, textVariants };
