'use client';

import { useRouter } from 'next/navigation';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { useStage, useModal } from '@/hooks';
import { LoginModal, type LoginModalProps } from '@/components/login-modal';

interface ProfileSidebarProps {
  slug: string;
}

export function ProfileSidebar({ slug }: ProfileSidebarProps) {
  const router = useRouter();
  const { openModal } = useModal();
  const { data: stage } = useStage(slug);

  const handleJoinToUnlock = () => {
    if (!stage) return;

    openModal<LoginModalProps, string>({
      component: LoginModal,
      props: {
        community: {
          id: stage.id,
          name: stage.name,
          image: stage.image as string | null,
          subscribersCount: stage.subscribersCount,
          owner: {
            name: stage.owner.name,
            image: stage.owner.image as string | null,
          },
        },
      },
      callbacks: {
        onClose: (result) => {
          if (result === 'success') {
            router.refresh();
          }
        },
      },
      settings: {
        closeOnOverlayClick: false,
      },
    });
  };

  return (
    <div className="space-y-4">
      {/* Upcoming Workshop */}
      <Card className="shadow-sm">
        <CardContent className="pt-6">
          <h3 className="font-semibold text-foreground mb-4">
            Upcoming Workshop
          </h3>
          <LockedContent onUnlock={handleJoinToUnlock}>
            <div className="flex items-center gap-3 mb-2">
              <div className="w-10 h-10 bg-purple-200 rounded-lg" />
              <div>
                <p className="font-medium text-sm">Workshop Title</p>
                <p className="text-xs text-muted-foreground">Coming soon</p>
              </div>
            </div>
          </LockedContent>
        </CardContent>
      </Card>

      {/* Ongoing Challenges */}
      <Card className="shadow-sm">
        <CardContent className="pt-6">
          <h3 className="font-semibold text-foreground mb-4">
            Ongoing Challenges
          </h3>
          <div className="space-y-3">
            {[1, 2].map((i) => (
              <LockedContent key={i} onUnlock={handleJoinToUnlock}>
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-2">
                    <div className="w-8 h-8 bg-purple-300 rounded-full border-2 border-background" />
                    <div className="w-8 h-8 bg-amber-300 rounded-full border-2 border-background" />
                    <div className="w-8 h-8 bg-pink-300 rounded-full border-2 border-background" />
                  </div>
                  <div className="flex-1">
                    <p className="font-medium text-sm">Challenge Title</p>
                    <p className="text-xs text-muted-foreground">
                      X participants
                    </p>
                  </div>
                </div>
              </LockedContent>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function LockedContent({
  children,
  onUnlock,
}: {
  children: React.ReactNode;
  onUnlock: () => void;
}) {
  return (
    <div className="bg-muted/50 rounded-lg p-4 relative overflow-hidden">
      <div className="blur-sm">{children}</div>
      <div className="absolute inset-0 flex items-center justify-center bg-background/60">
        <Button
          variant="outline"
          className="rounded-full gap-2 bg-background"
          onClick={onUnlock}
        >
          <span>🔒</span> Join to Unlock
        </Button>
      </div>
    </div>
  );
}
