'use client';

import {
  useQuery,
  useInfiniteQuery,
  UseQueryOptions,
} from '@tanstack/react-query';
import { api, ApiClientError } from '@/lib/api-client';
import { queryKeys } from '@/lib/query-keys';
import type { PostResponseDto, ListPostsResponseDto } from '@backstage-pass/api';

// ============================================
// Query Hooks
// ============================================

type UsePostOptions = Omit<
  UseQueryOptions<ListPostsResponseDto, ApiClientError>,
  'queryKey' | 'queryFn'
>;

export function usePost(postId: string, options?: UsePostOptions) {
  return useQuery<ListPostsResponseDto, ApiClientError>({
    queryKey: queryKeys.posts.detail(postId),
    queryFn: async () => {
      const { data } = await api.posts.postsControllerGetPost({ postId });
      return data.result;
    },
    enabled: !!postId,
    ...options,
  });
}

type UseStagePostsOptions = Omit<
  UseQueryOptions<PostResponseDto[], ApiClientError>,
  'queryKey' | 'queryFn'
>;

export function useStagePosts(
  stageId: string,
  options?: UseStagePostsOptions
) {
  return useQuery<PostResponseDto[], ApiClientError>({
    queryKey: queryKeys.posts.list(stageId),
    queryFn: async () => {
      const { data } = await api.posts.postsControllerListPosts({ stageId });
      return data.result.posts;
    },
    enabled: !!stageId,
    ...options,
  });
}

// ============================================
// Infinite Query Hook
// ============================================

export function useInfinitePosts(stageId: string) {
  return useInfiniteQuery({
    queryKey: queryKeys.posts.infinite(stageId),
    queryFn: async ({ pageParam }) => {
      const { data } = await api.posts.postsControllerListPosts({
        stageId,
        cursor: pageParam ?? undefined,
      });
      return data.result;
    },
    initialPageParam: null as string | null,
    getNextPageParam: (lastPage: ListPostsResponseDto) =>
      lastPage.nextCursor as string | null,
    select: (data) => data.pages.flatMap((page) => page.posts),
    enabled: !!stageId,
  });
}
